mapper.select:
select id, is_deleted, nezha_tenant_code, name, description, status, skill_id, category, source, mcp_endpoint, input_schema, trust_level, version, artifact_path, artifact_checksum, schema_version, create_at, create_by, create_name, update_at, update_by, update_name from skill_registry where is_deleted = 0
and name like concat('%', #{name,jdbcType=VARCHAR}, '%')
and status = #{status,jdbcType=VARCHAR}
and category = #{category,jdbcType=VARCHAR}
and source = #{source,jdbcType=VARCHAR}
order by id desc
